//! The seeded harness world as fake clusters: a snapshot of the kind clusters
//! `kind-kore-harness` (kore-demo, kore-rbac, kube-system) and
//! `kind-kore-harness-2` (kore-remote), regenerated by `fixtures/snapshot.sh`.
//!
//! Timestamps are shifted so the snapshot time is "now": ages read the same as
//! they did on the cluster when the snapshot was taken.

use crate::{FakeCluster, FakeEnv};
use chrono::{DateTime, Utc};
use serde_json::Value;

pub const CONTEXT: &str = "kind-kore-harness";
pub const CONTEXT_2: &str = "kind-kore-harness-2";

const HARNESS: &str = include_str!("../fixtures/kore-harness.json");
const HARNESS_2: &str = include_str!("../fixtures/kore-harness-2.json");
const LOGS: &str = include_str!("../fixtures/logs.json");

/// The `kind-kore-harness` cluster, with pod logs.
pub fn harness_cluster() -> FakeCluster {
    let c = load(HARNESS);
    let logs: serde_json::Map<String, Value> = serde_json::from_str(LOGS).expect("logs.json");
    for (key, lines) in logs {
        let mut parts = key.splitn(3, '/');
        let (ns, pod, container) = (parts.next().unwrap(), parts.next().unwrap(), parts.next().unwrap());
        let lines: Vec<&str> = lines.as_array().unwrap().iter().filter_map(Value::as_str).collect();
        c.set_logs(ns, pod, container, &lines);
    }
    c
}

/// The `kind-kore-harness-2` cluster (deploy `remote-web` in `kore-remote`).
pub fn harness_cluster_2() -> FakeCluster {
    load(HARNESS_2)
}

const HELM_FILES: &[(&str, &str)] = &[
    ("version.txt", include_str!("../fixtures/helm/version.txt")),
    ("list.json", include_str!("../fixtures/helm/list.json")),
    ("history.json", include_str!("../fixtures/helm/history.json")),
    ("values.yaml", include_str!("../fixtures/helm/values.yaml")),
    ("manifest.yaml", include_str!("../fixtures/helm/manifest.yaml")),
    ("notes.txt", include_str!("../fixtures/helm/notes.txt")),
];

/// Install a fake `helm` that answers like the seeded cluster's release
/// `kore-demo` (captured `helm` output). `rollback` / `uninstall` / `upgrade`
/// succeed without output; every call is recorded (see `FakeEnv::tool_calls`).
/// Override files in `<env dir>/helm/` to change answers mid-test.
pub fn with_helm(env: FakeEnv) -> FakeEnv {
    let dir = env.dir.path().join("helm");
    std::fs::create_dir_all(&dir).expect("helm fixture dir");
    for (name, body) in HELM_FILES {
        std::fs::write(dir.join(name), body).expect("helm fixture");
    }
    let d = dir.display();
    env.tool(
        "helm",
        &format!(
            r#"case "$1 $2" in
  "version "*) cat '{d}/version.txt' ;;
  "list "*) cat '{d}/list.json' ;;
  "history "*) cat '{d}/history.json' ;;
  "get values") cat '{d}/values.yaml' ;;
  "get manifest") cat '{d}/manifest.yaml' ;;
  "get notes") cat '{d}/notes.txt' ;;
  "rollback "*|"uninstall "*|"upgrade "*) exit 0 ;;
  *) echo "fake helm: unsupported $*" >&2; exit 1 ;;
esac"#
        ),
    )
}

/// Both harness contexts, `kind-kore-harness` current, like the kind setup.
pub fn harness_env() -> (FakeEnv, FakeCluster, FakeCluster) {
    let c1 = harness_cluster();
    let c2 = harness_cluster_2();
    let env = FakeEnv::new().context(CONTEXT, &c1).context(CONTEXT_2, &c2);
    (env, c1, c2)
}

fn load(json: &str) -> FakeCluster {
    let mut list: Value = serde_json::from_str(json).expect("fixture JSON");
    let snapshot: DateTime<Utc> = list["snapshotTime"].as_str().and_then(|s| s.parse().ok()).unwrap_or_else(Utc::now);
    let shift = Utc::now() - snapshot;
    shift_times(&mut list, shift);
    let c = FakeCluster::new();
    let items = list["items"].as_array().cloned().unwrap_or_default();
    // CRDs first so their instances' types are known.
    let (crds, rest): (Vec<Value>, Vec<Value>) = items.into_iter().partition(|i| i["kind"] == "CustomResourceDefinition");
    for item in crds.into_iter().chain(rest) {
        c.apply(item);
    }
    c
}

fn shift_times(v: &mut Value, shift: chrono::Duration) {
    match v {
        Value::String(s) if looks_like_time(s) => {
            if let Ok(t) = s.parse::<DateTime<Utc>>() {
                let fmt = if s.contains('.') { chrono::SecondsFormat::Micros } else { chrono::SecondsFormat::Secs };
                *s = (t + shift).to_rfc3339_opts(fmt, true);
            }
        }
        Value::Array(a) => a.iter_mut().for_each(|x| shift_times(x, shift)),
        Value::Object(o) => o.iter_mut().for_each(|(_, x)| shift_times(x, shift)),
        _ => {}
    }
}

fn looks_like_time(s: &str) -> bool {
    let b = s.as_bytes();
    b.len() >= 20 && b[4] == b'-' && b[7] == b'-' && b[10] == b'T' && b[13] == b':' && s.ends_with('Z')
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn harness_world_loads() {
        let c = harness_cluster();
        let pods = c.list("Pod", Some("kore-demo"));
        assert!(pods.iter().any(|p| p["metadata"]["name"] == "crashloop"));
        assert!(c.list("Widget", Some("kore-demo")).len() >= 2);
        assert_eq!(harness_cluster_2().list("Deployment", Some("kore-remote")).len(), 1);
    }
}
